<?php declare(strict_types=1); namespace Annam; $title='Store settings';$subtitle='Your name, logo, colours and the words on your home page.'; ?>
<form class="o-form" method="post" enctype="multipart/form-data"><?= csrf() ?><section class="o-card"><header class="o-card-head"><h2>Your store</h2></header><div class="o-grid-form"><?php foreach(['brand_name'=>'Store name','tagline'=>'Tagline','support_phone'=>'Phone / WhatsApp'] as $key=>$label): ?><label class="o-field"><span><?= e($label) ?></span><input name="<?= e($key) ?>" value="<?= e($store->config[$key]) ?>" <?= $key==='brand_name'?'required':'' ?>></label><?php endforeach; ?><label class="o-field"><span>Email</span><input type="email" name="contact_email" value="<?= e($website->copy['footer.email']) ?>"></label></div></section>
<section class="o-card"><header class="o-card-head"><h2>Look</h2></header><div class="o-grid-form"><label class="o-field"><span>Brand colour</span><span class="o-color"><input name="brand_color" type="color" value="<?= e($store->config['theme']['brand']??'#FF8507') ?>"><code data-color-value><?= e($store->config['theme']['brand']??'#FF8507') ?></code></span><small>Buttons, highlights and the top strip use this colour.</small></label><div class="o-field"><span>Logo</span><label class="o-drop o-drop-sm" data-drop><img class="o-drop-preview" data-preview src="<?= e($store->logo()) ?>" alt="Current logo"><span class="o-drop-hint"><b>Drop your logo</b> or click<small>PNG or JPG, 5 MB max.</small></span><input type="file" name="logo" accept="image/jpeg,image/png,image/webp"></label></div><label class="o-field o-field-wide"><span>Announcements</span><textarea name="announcements"><?= e(implode("\n",$store->config['theme']['announcements']??[])) ?></textarea><small>One message per line. They scroll in the strip at the top.</small></label></div></section>
<section class="o-card"><header class="o-card-head"><h2>Home page hero</h2><a href="/" target="_blank" rel="noopener">Preview →</a></header><div class="o-grid-form"><?php foreach(['kicker'=>'Hero: small heading','title'=>'Hero: headline','body'=>'Hero: introduction'] as $key=>$label): ?><label class="o-field <?= $key==='body'?'o-field-wide':'' ?>"><span><?= e($label) ?></span><textarea name="hero_<?= e($key) ?>"><?= e($website->copy['hero.'.$key]) ?></textarea></label><?php endforeach; ?></div></section>
<section class="o-card"><header class="o-card-head"><h2>Ordering</h2></header><?php foreach(['website_ordering'=>'Take orders on the website','snacks_courier'=>'Enable the shop','carry_forward_meals'=>'Keep the latest saved breakfast, lunch and dinner menu until changed'] as $key=>$label): ?><label class="o-check"><input type="checkbox" name="<?= e($key) ?>" value="1" <?= ($store->config['features'][$key]??true)?'checked':'' ?>><span class="o-switch-ui"><i></i></span><b><?= e($label) ?></b></label><?php endforeach; ?><details><summary>Payment options and preview testing</summary><p>Normal checkout requires enabled live Razorpay. Temporary test/manual checkout can be used while reviewing the preview.</p><?php foreach(['checkout_test_mode'=>'Enable temporary test / manual checkout','manual_payments'=>'Allow manual payment arrangements','cod'=>'Allow cash on delivery'] as $key=>$label): ?><label class="o-check"><input type="checkbox" name="<?= e($key) ?>" value="1" <?= !empty($store->config['features'][$key])?'checked':'' ?>><span class="o-switch-ui"><i></i></span><b><?= e($label) ?></b></label><?php endforeach; ?></details></section>
<section class="o-card"><h2>Contact address</h2><label class="o-field"><span>Public contact address</span><textarea name="footer_address"><?= e($website->copy['footer.address']) ?></textarea></label></section><div class="o-form-bar"><button class="o-btn o-btn-primary">Save settings</button></div></form><section class="o-card"><h2>Photo backup</h2><p>Download referenced photos and a missing-file report. Back up the database and private encryption keys separately.</p><form method="post" action="/manage/settings/media-backup/"><?= csrf() ?><button class="o-btn">Download media ZIP</button></form></section>
